def findOrder(dict, N, K):
    # Create a graph to represent the order of characters
    graph = {char: set() for char in range(K)}
    in_degree = {char: 0 for char in range(K)}

    # Create the graph based on the given dictionary
    for i in range(N - 1):
        word1, word2 = dict[i], dict[i + 1]
        min_len = min(len(word1), len(word2))
        for j in range(min_len):
            if word1[j] != word2[j]:
                if word2[j] not in graph[ord(word1[j]) - ord('a')]:
                    graph[ord(word1[j]) - ord('a')].add(ord(word2[j]) - ord('a'))
                    in_degree[ord(word2[j]) - ord('a')] += 1
                break

    # Topological sort using Kahn's algorithm
    queue = []
    for i in range(K):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.pop(0)
        result.append(chr(node + ord('a')))
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    # If the result does not contain all characters, it means there was a cycle
    if len(result) != K:
        return ""

    return ''.join(result)
